package com.rescuefarm.ui.engagement;
import androidx.lifecycle.*;import com.rescuefarm.data.repository.EngagementRepository;import com.rescuefarm.domain.enums.*;import com.rescuefarm.domain.model.*;import java.util.*;
public class EngagementViewModel extends ViewModel{private final EngagementRepository repo;private final MutableLiveData<EngagementState> state=new MutableLiveData<>(EngagementState.idle());public EngagementViewModel(EngagementRepository r){repo=r;}public LiveData<EngagementState> getState(){return state;}public LiveData<List<Favorite>> favorites(){return repo.observeFavorites();}public LiveData<Boolean> observeFavorite(String uid,String productId){return repo.observeFavorite(uid,productId);}public LiveData<List<Review>> reviews(){return repo.observeProductReviews();}public LiveData<List<Report>> reports(){return repo.observeReports();}public LiveData<List<Notification>> notifications(){return repo.observeNotifications();}
 public void refreshFavorites(String uid){loading();repo.refreshFavorites(uid,action());}public void toggleFavorite(String uid,String pid){loading();repo.toggleFavorite(uid,pid,new EngagementRepository.FavoriteCallback(){public void onSuccess(boolean f){state.postValue(EngagementState.success(f?"Đã thêm yêu thích.":"Đã bỏ yêu thích."));}public void onError(EngagementRepository.ErrorCode c,String m){error(m);}});}
 public void refreshReviews(String pid){loading();repo.refreshProductReviews(pid,action());}public void saveReview(Review r,boolean update){saveReview(r,update,null);}public void saveReview(Review r,boolean update,Runnable onSaved){loading();repo.saveReview(r,update,new EngagementRepository.ReviewCallback(){public void onSuccess(Review x){state.postValue(EngagementState.success("Đã lưu review đã mua hàng."));if(onSaved!=null)onSaved.run();refreshReviews(x.getProductId());}public void onError(EngagementRepository.ErrorCode c,String m){error(m);}});}public void deleteReview(String id,String productId){deleteReview(id,productId,null);}public void deleteReview(String id,String productId,Runnable onDeleted){loading();repo.deleteReview(id,new EngagementRepository.ActionCallback(){public void onSuccess(){state.postValue(EngagementState.success("Đã xóa review."));if(onDeleted!=null)onDeleted.run();refreshReviews(productId);}public void onError(EngagementRepository.ErrorCode c,String m){error(m);}});}
 public void report(String uid,ReportTargetType t,String id,String reason,String description){loading();repo.createReport(uid,t,id,reason,description,new EngagementRepository.ReportCallback(){public void onSuccess(Report r){state.postValue(EngagementState.success("Đã gửi báo cáo để kiểm duyệt."));}public void onError(EngagementRepository.ErrorCode c,String m){error(m);}});}public void refreshReports(){repo.refreshReports(action());}public void transitionReport(String id,ReportStatus target,String note){loading();repo.transitionReport(id,target,note,new EngagementRepository.ReportCallback(){public void onSuccess(Report r){state.postValue(EngagementState.success("Đã cập nhật report: "+r.getStatus().name()));refreshReports();}public void onError(EngagementRepository.ErrorCode c,String m){error(m);}});}
 public void refreshNotifications(String uid){repo.refreshNotifications(uid,action());}public void markRead(String id,String uid){repo.markNotificationRead(id,new EngagementRepository.ActionCallback(){public void onSuccess(){refreshNotifications(uid);}public void onError(EngagementRepository.ErrorCode c,String m){error(m);}});}public void registerToken(String uid,String token){repo.registerFcmToken(uid,token,action());}
 private void loading(){state.setValue(EngagementState.loading());}private void error(String m){state.postValue(EngagementState.error(m));}private EngagementRepository.ActionCallback action(){return new EngagementRepository.ActionCallback(){public void onSuccess(){state.postValue(EngagementState.success("Đã đồng bộ."));}public void onError(EngagementRepository.ErrorCode c,String m){error(m);}};}@Override protected void onCleared(){repo.close();}}
